          "title": "你是熟悉國中七年級國文程度的國中七年級國文老師，請根據中國宋代作家蘇軾所著的\"記承天夜遊\"文章設計短劇，完成一個用繁體中文呈現的有對話的劇本，記承天夜遊原文如下",
          "body": "<p>元豐六年十月十二日夜，解衣欲睡，月色入戶，欣然起行。念無與爲樂者，遂至承天寺尋張懷民。懷民亦未寢，相與步於中庭。庭下如積水空明，水中藻、荇交橫，蓋竹柏影也。何夜無月？何處無竹​​柏？但少閒人如吾兩人耳。</p>",
