          "body": "<p>1. <strong>木蘭辭的主題是什麼？</strong>  </p><p>   A) 家庭責任  </p><p>   B) 戰爭勇氣  </p><p>   C) 女性獨立  </p><p>   D) 自然美景  </p><p>2. <strong>木蘭為何代父從軍？</strong>  </p><p>   A) 父親生病  </p><p>   B) 家中經濟困難  </p><p>   C) 她想要冒險  </p><p>   D) 父親年老無法上戰場  </p><p>3. <strong>木蘭在出征前做了哪些準備？</strong>  </p><p>   A) 購買馬匹和武器  </p><p>   B) 學習文學  </p><p>   C) 與朋友聚會  </p><p>   D) 旅行  </p><p>4. <strong>詩中提到的「東市買駿馬」意義為何？</strong>  </p><p>   A) 代表她的勇氣  </p><p>   B) 象徵她的決心  </p><p>   C) 表示對戰爭的期待  </p><p>   D) 隱喻家庭的支持  </p><p>5. <strong>木蘭在軍中表現如何？</strong>  </p><p>   A) 獲得讚賞和獎勵  </p><p>   B) 遭遇困難和挫折  </p><p>   C) 被同袍排擠  </p><p>   D) 不斷失敗  </p><p>6. <strong>詩中「十年戎馬」的意思是什麼？</strong>  </p><p>   A) 她在軍中待了十年  </p><p>   B) 她經歷了十場戰役  </p><p>   C) 她在戰爭中長大  </p><p>   D) 她為國家奉獻了十年  </p><p>7. <strong>木蘭回家後，最重要的情感是什麼？</strong>  </p><p>   A) 喜悅與驕傲  </p><p>   B) 懷念與孤獨  </p><p>   C) 愧疚與不安  </p><p>   D) 平靜與安詳  </p><p>8. <strong>詩中「不聞爺娘喚女聲」有何含義？</strong>  </p><p>   A) 忘記家庭的呼喚  </p><p>   B) 專注於軍事任務  </p><p>   C) 對家庭的不滿意  </p><p>   D) 渴望自由生活  </p><p>9. <strong>木蘭辭所反映的社會價值觀是什麼？</strong>  </p><p>   A) 男性主義優越感  </p><p>   B) 家庭與國家的責任感  </p><p>   C) 個人自由的重要性  </p><p>   D) 戰爭的必要性  </p><p>10. <strong>詩中使用了哪些修辭手法？</strong>  </p><p>    A) 比喻和擬人法   </p><p>    B) 排比和對偶   </p><p>    C) 反諷和誇張   </p><p>    D) 隱喻和象徵</p><p><br></p><p><br></p>",
