          "id": "3229550515",
          "title": "一步步思考，你是熟悉國中九年級國文程度的國中",
          "body": "<p>一步步思考，你是熟悉國中九年級國文程度的國中國文老師，請根據余秋雨的〈蘇東坡突圍〉文章最後一段：成熟是一種明亮而不刺眼的光輝，一種圓潤而不膩耳的音響，一種不再需要對別人察顏觀色的從容，一種終於停止向周圍申訴求告的大氣，一種不理會哄鬧的微笑，一種洗刷了偏激的淡漠，一種無須聲張的厚實，一種並不陡峭的高度。勃鬱的豪情發過了酵，尖利的山風收住了勁，湍急的細流匯成了湖，結果── 引導千古傑作的前奏已經鳴響，一道神祕的天光射向黃州，念奴嬌•赤壁懷古和前後赤壁賦馬上就要產生。 設計4則閱讀理解題目給國中九年級的學生，每個題目四個答案選項,其中難度中等以上題目2題，其他2題適合程度較弱的學生作答。</p>",
