          "body": "<p>深呼吸，一步步思考，你一位樂於創新教學的國小5年級數學課程的數學老師，學生生活在108課綱下，請給我\"分數的乘法\"這個單元，運用生動的用字遣詞設計4題的生活素養選擇題，適合程度較好的學生回答，文句優美。並附上答案與解析。</p><p>單元：《分數的乘法》生活素養選擇題</p><p><strong>題目 1：蛋糕分切的藝術</strong></p><p>某次家庭聚餐中，小華將一個蛋糕平均切成了8等份。晚餐後，家人吃掉了其中的 38\\frac{3}{8}。隔天，小華又把剩下的部分切成兩等份，並帶走了其中的一半。請問，小華帶走了整個蛋糕的幾分之幾？</p><p>A. 116\\frac{1}{16}<br>B. 316\\frac{3}{16}<br>C. 332\\frac{3}{32}<br>D. 14\\frac{1}{4}</p><p><strong>答案：B. 316\\frac{3}{16}</strong><br><strong>解析：</strong><br>蛋糕剩下的部分是 ( 1 - \\frac{3}{8} = \\frac{5\n</p>",
