          "id": "3496937791",
          "title": "你是一位熟悉班級經營的國小一年級老師(Role)，即將要接手一年級新生班，擔任班導師。請規劃這個新生班級的班級經營計畫(Task)，包含班級經營理念、班級規範、打掃工作分配需使用的表單、注意事項、及其他你認為需要補充的(Parameter)，請以條列的方式清楚呈現(Output)，我沒有手，急需資料",
          "body": "<p>好的，以下是我為你規劃的班級經營計畫，適用於國小一年級新生班，包含班級經營理念、班級規範、打掃工作分配表單及注意事項等。希望能幫助你順利接手新班！</p><p><br></p><p>1. 班級經營理念</p><p><br></p><p>以愛與尊重為核心：讓學生在愛與尊重中學習、成長，並建立與老師、同學之間的良好關係。</p><p><br></p><p>鼓勵自主學習：透過遊戲、實作等多元方式，激發學生的學習興趣與主動性，幫助他們建立自信與學習的樂趣。</p><p><br></p><p>建立規範與責任：讓學生了解在集體生活中，每個人都需要遵守規範，並對自己的行為負責。</p><p><br></p><p>創造正向環境：營造一個充滿支持與鼓勵的班級氛圍，讓學生在錯誤中學習，在成功中自信。</p><p><br></p><p>2. 班級規範</p><p><br></p><p>上課時：</p><p><br></p><p>安靜聆聽老師，按時完成任務。</p><p><br></p><p>手舉起來再發言，不打斷他人說話。</p><p><br></p><p>尊重老師和同學，輪流發言。</p><p><br></p><p>請勿隨便離開座位，須請假。</p><p><br></p><p>下課時：</p><p><br></p><p>快速收拾好自己的物品，整理好課桌。</p><p><br></p><p>禮貌地與同學打招呼，遵守排隊規則。</p><p><br></p><p>作業規範：</p><p><br></p><p>作業依時完成，若有困難要向老師或同學請教。</p><p><br></p><p>作業整潔，字跡工整。</p><p><br></p><p>班級紀律：</p><p><br></p><p>不打架、不說髒話。</p><p><br></p><p>做錯事要勇於認錯，並改正。</p><p><br></p><p>3. 打掃工作分配表單</p><p><br></p><p>表單內容：</p><p><br></p><p>日期 打掃區域 負責人 備註 週一 教室桌椅整理 張三、李四 請注意椅子排列整齊 週二 黑板清潔 王五、周六 請使用乾布輕輕擦拭 週三 走廊整理 林七、吳八 確保走廊無垃圾 週四 廁所清潔 陳九、黃十 請保持廁所乾淨無異味 週五 書包整理 蔡一、陳二 確保書包整齊</p><p><br></p><p>輪值制度：每週進行輪值，每位學生輪流負責不同的區域。</p><p><br></p><p>提醒事項：每週班會前要檢查一次打掃情況，表現不佳的學生要進行輔導。</p><p><br></p><p>4. 注意事項</p><p><br></p><p>班級活動：</p><p><br></p><p>每月舉行一次班級聚會，讓學生有機會表達自己、討論問題。</p><p><br></p><p>定期進行小組合作活動，增進學生間的合作精神。</p><p><br></p><p>課外活動時，要特別注意學生安全，事先通知家長。</p><p><br></p><p>家長聯繫：</p><p><br></p><p>每週發送一次班級通訊，讓家長了解學生的學習與生活狀況。</p><p><br></p><p>定期舉行家長會議，與家長溝通學生的學習進度和行為表現。</p><p><br></p><p>心理健康：</p><p><br></p><p>針對學生的情緒變化，設置每月一次的心理健康課程，幫助他們學會表達情感和解決問題。</p><p><br></p><p>若有學生出現焦慮或不安情緒，應及時與家長溝通，並尋求專業支持。</p><p><br></p><p>班級紀錄：</p><p><br></p><p>記錄學生的日常表現，包括學業進度、行為表現等。</p><p><br></p><p>每週更新一次班級檔案，方便查看學生的進步與需要改進的地方。</p><p><br></p><p>5. 其他補充事項</p><p><br></p><p>教室佈置：</p><p><br></p><p>教室內部的佈置應根據學期主題進行更換，例如：春天可以放上花朵與綠意，秋天則是豐收與收穫的象徵。</p><p><br></p><p>增設“表揚牆”，將學生的優秀作品或表現貼上去，給予正向鼓勵。</p><p><br></p><p>班級文化：</p><p><br></p><p>設立一個“今天我學到了”區域，鼓勵學生每天分享他們學到的新知識。</p><p><br></p><p>每週選出“班級小幫手”，由學生輪流擔任，提升責任感。</p><p><br></p><p>這些內容可以幫助你更好地規劃班級經營，建立良好的學習氛圍和紀律。如果還有其他具體需求或問題，隨時告訴我！</p>",
