          "color_label": "資料",
          "color_name": "white",
          "badge_class": "bg-amber-100 text-amber-800 border-amber-300 dark:bg-amber-900/40 dark:text-amber-200",
          "local_image": "assets/images/pa_img_3496950407.png",
          "local_file": "",
