      "title": "你是一位國小三年級的國語老師，請設計兩篇以海",
      "body": "<p>你是一位國小三年級的國語老師，請設計兩篇以海洋為主題，適合給學生做仿寫格式練習的新詩</p><p>的新詩</p>",
