      "id": "2958116493",
      "title": "你是熟悉明鄭時期的社會老師(Role)，設計3題關於\"明鄭統治台灣\"的選擇題，並附上答案與解析(Task)，請盡量用優美的詞句作為題目，不要用markdown語法(Parameter)，用來測驗國小五年級學生，請條列清楚(Output)",
