      "id": "2978922643",
      "title": "你是熟悉國中七年級自然課程的自然老師，請你以國中翰林七下自然動物界為版本，設計符合10題的閱讀理解的素養選擇題目，適合程度較好的學生回答，文句優美。並附上解析。",
      "body": "<p>當然，以下是我為您設計的10題閱讀理解的素養選擇題目，適合程度較好的學生回答。每題都附有解析。</p><ol><li><p><strong>下列哪種動物是節肢動物？</strong> A. 蝴蝶 B. 蛇 C. 蜘蛛 D. 熊 <em>解析：答案是C，蜘蛛是節肢動物。</em></p></li><li><p><strong>下列哪種動物是兩棲類？</strong> A. 鱷魚 B. 青蛙 C. 鯨魚 D. 老鷹 <em>解析：答案是B，青蛙是兩棲類。</em></p></li><li><p><strong>下列哪種動物是哺乳類？</strong> A. 鱷魚 B. 青蛙 C. 鯨魚 D. 老鷹 <em>解析：答案是C，鯨魚是哺乳類。</em></p></li><li><p><strong>下列哪種動物是鳥類？</strong> A. 鱷魚 B. 青蛙 C. 鯨魚 D. 老鷹 <em>解析：答案是D，老鷹是鳥類。</em></p></li><li><p><strong>下列哪種動物是爬蟲類？</strong> A. 鱷魚 B. 青蛙 C. 鯨魚 D. 老鷹 <em>解析：答案是A，鱷魚是爬蟲類。</em></p></li><li><p><strong>下列哪種動物是昆蟲？</strong> A. 蝴蝶 B. 蛇 C. 蜘蛛 D. 熊 <em>解析：答案是A，蝴蝶是昆蟲。</em></p></li><li><p><strong>下列哪種動物是魚類？</strong> A. 鱷魚 B. 青蛙 C. 鯨魚 D. 鯉魚 <em>解析：答案是D，鯉魚是魚類。</em></p></li><li><p><strong>下列哪種動物是無脊椎動物？</strong> A. 蝴蝶 B. 蛇 C. 蜘蛛 D. 熊 <em>解析：答案是C，蜘蛛是無脊椎動物。</em></p></li><li><p><strong>下列哪種動物是有脊椎的？</strong> A. 蝴蝶 B. 蛇 C. 蜘蛛 D. 熊 <em>解析：答案是B，蛇是有脊椎的動物。</em></p></li><li><p><strong>下列哪種動物是哺乳動物？</strong> A. 蛇 B. 鳥 C. 魚 D. 熊 <em>解析：答案是D，熊是哺乳動物。</em></p></li></ol><p>希望這些題目能對您有所幫助！</p>",
