      "id": "2991963479",
      "title": "你是熟悉各種球類知識的國中健康與體育老師(R",
      "body": "<p>你是熟悉各種球類知識的國中健康與體育老師(Role)，請設計5題關於\"游泳\"的選擇題，並附上答案與解析(Task)，請盡量用優美的詞句作為題目，不要用markdown語法(Parameter)，用來測驗國中八年級學生，請條列清楚(Output)</p><p>ChatGPT</p><p><strong>ChatGPT</strong></p><p>當然可以！這是我設計的游泳知識測驗：</p><ol><li><p>在游泳比賽中，常用的游泳姿勢有哪一種？ a) 蝶式 b) 仰式 c) 蛙式 d) 自由式 正確答案：d) 自由式 解析：自由式是最常見也是最自由的游泳姿勢，選手可以自由選擇手臂和腿的動作節奏。</p></li><li><p>游泳時，呼吸的頻率應該是？ a) 每三拍呼吸一次 b) 每四拍呼吸一次 c) 每五拍呼吸一次 d) 每六拍呼吸一次 正確答案：b) 每四拍呼吸一次 解析：游泳時，保持每四拍呼吸一次的頻率有助於保持呼吸節奏與游泳動作的協調。</p></li><li><p>在游泳比賽中，使用蛙式游泳的選手主要使用哪個呼吸方式？ a) 嘴呼吸 b) 鼻呼吸 c) 喉嚨呼吸 d) 鼻孔呼吸 正確答案：c) 喉嚨呼吸 解析：使用蛙式游泳時，選手通常將臉部浸入水中，透過喉嚨呼吸。</p></li><li><p>在游泳時，選手應該保持身體的什麼部位浮在水面上？ a) 腰部 b) 胸部 c) 头部 d) 腿部 正確答案：c) 头部 解析：保持头部浮在水面上有助於保持呼吸暢通，使游泳更加輕鬆。</p></li><li><p>下列哪項是游泳時應該注意的安全原則？ a) 單獨游泳 b) 穿著大量浮具 c) 在水深處嘗試新姿勢 d) 忽略泳池的警告標誌 正確答案：a) 單獨游泳 解析：獨自游泳時，若發生意外，可能無人及時相助，因此應盡量避免單獨游泳，特別是在無救生員監督的情況下。</p></li></ol><p><br></p>",
