      "title": "你是一位高一英文老師，請就Taiwan's first break-dancing boy to compete in the Summer Olympics in Paris.這個議題，出5題英文閱讀測驗，每一題有4個選項，B2程度。並附上解析",
      "body": "<p><strong>答案</strong></p><p><strong>Reading Comprehension Questions on Taiwan's First Break-Dancing Olympian</strong></p><ol><li><p><strong>Who is Taiwan's first B-Boy to qualify for the Olympic breakdancing competition?</strong>A) Qi Xiangyu<br>B) Su Chih-peng<br>C) Sun Chen<br>D) B-boy Lithe-ing<strong>Correct Answer:</strong> C) Sun Chen<br><strong>Explanation:</strong> Sun Chen, also known as \"B-Boy Quake,\" is recognized as Taiwan's first B-Boy to qualify for the Olympic breakdancing competition in Paris 2024.</p></li><li><p><strong>In which two cities were the Olympic Qualifier Series for breakdancing held?</strong>A) Tokyo and Seoul<br>B) Shanghai and Budapest<br>C) Paris and London<br>D) New York and Los Angeles<strong>Correct Answer:</strong> B) Shanghai and Budapest<br><strong>Explanation:</strong> The Olympic Qualifier Series for breakdancing took place in Shanghai, China, and Budapest, Hungary.</p></li><li><p><strong>What injury did Sun Chen compete with during the qualifiers?</strong>A) Arm injury<br>B) Leg injury<br>C) Back injury<br>D) Ankle injury<strong>Correct Answer:</strong> B) Leg injury<br><strong>Explanation:</strong> Sun Chen competed with a leg injury during the qualifiers and used painkillers to manage the pain.</p></li><li><p><strong>What was Sun Chen's overall ranking in the combined results from both qualifiers?</strong>A) 7th<br>B) 10th<br>C) 15th<br>D) 5th<strong>Correct Answer:</strong> B) 10th<br><strong>Explanation:</strong> Sun Chen placed 10th overall in the combined results from the qualifiers in Shanghai and Budapest, which allowed him to qualify for the Olympics.</p></li><li><p><strong>What did Sun Chen's coach hope for the future of breakdancing in Taiwan after Sun's qualification?</strong>A) More competitions<br>B) Increased funding for dancers<br>C) Greater recognition of breakdancing as a sport<br>D) More international partnerships<strong>Correct Answer:</strong> C) Greater recognition of breakdancing as a sport<br><strong>Explanation:</strong> Sun Chen's coach, Su Chih-peng, expressed hope that Taiwan would begin to value breakdancing as a sport and invest more in its development after Sun's historic qualification for the Olympics.</p></li></ol>",
