      "id": "3091310832",
      "title": "你是熟悉國中九年級社會課程的地理老師，請給我\"歐洲\"這個單元，設計5題的生活素養選擇題，5題具有素養的題組題，最好能搭配圖表來測驗學生空間概念，難易度適中，文句明確說明。並附上答案與解析。",
      "body": "<p>### 生活素養選擇題</p><p><strong>1. 在歐洲有一個國家被稱為「國家之都」，它是因為擁有世界上最古老的持續存在的國會而聞名。這個國家是哪一個？</strong></p><p>A) 法國  </p><p>B) 英國  </p><p>C) 德國  </p><p>D) 荷蘭  </p><p><strong>答案：</strong> B) 英國  </p><p><strong>解析：</strong> 英國的國會（Houses of Parliament）是世界上最古老的持續存在的國會機構之一。</p><p><strong>2. 哪個歐洲國家在二戰後，成功實現了快速的經濟復甦，成為「經濟奇蹟」的代表？</strong></p><p>A) 法國  </p><p>B) 瑞士  </p><p>C) 德國  </p><p>D) 意大利  </p><p><strong>答案：</strong> C) 德國  </p><p><strong>解析：</strong> 德國在二戰後實現了「經濟奇蹟」，其快速的經濟增長被稱為「Wirtschaftswunder」。</p><p><strong>3. 如果你在夏天參觀瑞士，哪一種自然景觀最有可能成為你的旅遊亮點？</strong></p><p>A) 沙漠  </p><p>B) 冰川  </p><p>C) 熱帶雨林  </p><p>D) 草原  </p><p><strong>答案：</strong> B) 冰川  </p><p><strong>解析：</strong> 瑞士以其壯觀的冰川景觀而聞名，特別是在阿爾卑斯山脈地區。</p><p><strong>4. 在歐洲的哪個國家，你可以找到最大的古羅馬遺址——羅馬競技場？</strong></p><p>A) 西班牙  </p><p>B) 法國  </p><p>C) 意大利  </p><p>D) 希臘  </p><p><strong>答案：</strong> C) 意大利  </p><p><strong>解析：</strong> 羅馬競技場（Colosseum）是意大利最著名的古羅馬遺址之一，位於羅馬市中心。</p><p><strong>5. 在歐洲，如果你想體驗最著名的酒莊之旅，你應該前往哪個國家？</strong></p><p>A) 法國  </p><p>B) 荷蘭  </p><p>C) 瑞士  </p><p>D) 瑞典  </p><p><strong>答案：</strong> A) 法國  </p><p><strong>解析：</strong> 法國以其酒莊聞名於世，尤其是波爾多和香檳地區。</p><p>### 具有素養的題組題</p><p><strong>題組題：</strong></p><p><strong>題目：</strong> 請參考下面的圖表，回答以下問題。圖表顯示了2023年歐洲各國的平均氣溫（攝氏度）和降水量（毫米）。</p><p><strong>圖表描述：</strong></p><p>- A國：氣溫 10°C，降水量 500 mm  </p><p>- B國：氣溫 15°C，降水量 700 mm  </p><p>- C國：氣溫 20°C，降水量 900 mm  </p><p>- D國：氣溫 25°C，降水量 200 mm  </p><p><strong>問題1：</strong> 哪個國家的氣溫最高？  </p><p><strong>A)</strong> A國  </p><p><strong>B)</strong> B國  </p><p><strong>C)</strong> C國  </p><p><strong>D)</strong> D國  </p><p><strong>答案：</strong> D) D國  </p><p><strong>解析：</strong> 根據圖表，D國的氣溫為25°C，是最高的。</p><p><strong>問題2：</strong> 哪個國家的降水量最少？  </p><p><strong>A)</strong> A國  </p><p><strong>B)</strong> B國  </p><p><strong>C)</strong> C國  </p><p><strong>D)</strong> D國  </p><p><strong>答案：</strong> D) D國  </p><p><strong>解析：</strong> D國的降水量為200毫米，是最少的。</p><p><strong>問題3：</strong> 如果你要選擇一個降水量最多的國家來進行植物學研究，應選擇哪個國家？  </p><p><strong>A)</strong> A國  </p><p><strong>B)</strong> B國  </p><p><strong>C)</strong> C國  </p><p><strong>D)</strong> D國  </p><p><strong>答案：</strong> C) C國  </p><p><strong>解析：</strong> C國的降水量為900毫米，是最多的。</p><p><strong>問題4：</strong> 根據圖表，哪個國家的氣候最為乾燥？  </p><p><strong>A)</strong> A國  </p><p><strong>B)</strong> B國  </p><p><strong>C)</strong> C國  </p><p><strong>D)</strong> D國  </p><p><strong>答案：</strong> D) D國  </p><p><strong>解析：</strong> D國的降水量最少，氣候最乾燥。</p><p><strong>問題5：</strong> 哪個國家的氣溫和降水量都中等？  </p><p><strong>A)</strong> A國  </p><p><strong>B)</strong> B國  </p><p><strong>C)</strong> C國  </p><p><strong>D)</strong> D國  </p><p><strong>答案：</strong> B) B國  </p><p><strong>解析：</strong> B國的氣溫和降水量都在中等範圍（氣溫15°C，降水量700毫米）。</p><p>這樣的題目不僅考察學生的知識，也幫助他們理解如何分析和解讀圖表中的空間和數據信息。希望這些題目能幫助你的教學！</p>",
