      "body": "<p>你是一名國中英語教師，請設計一個英語日活動，這個活動需利用下課10分鐘進行，並包含強化學生聽、說的活動。活動需涵蓋2項南非文化比較的學習內容，不播放影片，請用表格呈現。</p>",
