      "body": "<p>好的，以下是我為你規劃的班級經營計畫，適用於國小一年級新生班，包含班級經營理念、班級規範、打掃工作分配表單及注意事項等。希望能幫助你順利接手新班！</p><p>1. <strong>班級經營理念</strong></p><ul><li><p><strong>以愛與尊重為核心</strong>：讓學生在愛與尊重中學習、成長，並建立與老師、同學之間的良好關係。</p></li><li><p><strong>鼓勵自主學習</strong>：透過遊戲、實作等多元方式，激發學生的學習興趣與主動性，幫助他們建立自信與學習的樂趣。</p></li><li><p><strong>建立規範與責任</strong>：讓學生了解在集體生活中，每個人都需要遵守規範，並對自己的行為負責。</p></li><li><p><strong>創造正向環境</strong>：營造一個充滿支持與鼓勵的班級氛圍，讓學生在錯誤中學習，在成功中自信。</p></li></ul><p>2. <strong>班級規範</strong></p><ul><li><p><strong>上課時</strong>：</p><ul><li><p>安靜聆聽老師，按時完成任務。</p></li><li><p>手舉起來再發言，不打斷他人說話。</p></li><li><p>尊重老師和同學，輪流發言。</p></li><li><p>請勿隨便離開座位，須請假。</p></li></ul></li><li><p><strong>下課時</strong>：</p><ul><li><p>快速收拾好自己的物品，整理好課桌。</p></li><li><p>禮貌地與同學打招呼，遵守排隊規則。</p></li></ul></li><li><p><strong>作業規範</strong>：</p><ul><li><p>作業依時完成，若有困難要向老師或同學請教。</p></li><li><p>作業整潔，字跡工整。</p></li></ul></li><li><p><strong>班級紀律</strong>：</p><ul><li><p>不打架、不說髒話。</p></li><li><p>做錯事要勇於認錯，並改正。</p></li></ul></li></ul><p>3. <strong>打掃工作分配表單</strong></p><ul><li><p><strong>表單內容</strong>：</p><p>日期 打掃區域 負責人 備註 週一 教室桌椅整理 張三、李四 請注意椅子排列整齊 週二 黑板清潔 王五、周六 請使用乾布輕輕擦拭 週三 走廊整理 林七、吳八 確保走廊無垃圾 週四 廁所清潔 陳九、黃十 請保持廁所乾淨無異味 週五 書包整理 蔡一、陳二 確保書包整齊</p><ul><li><p><strong>輪值制度</strong>：每週進行輪值，每位學生輪流負責不同的區域。</p></li><li><p><strong>提醒事項</strong>：每週班會前要檢查一次打掃情況，表現不佳的學生要進行輔導。</p></li></ul></li></ul><p>4. <strong>注意事項</strong></p><ul><li><p><strong>班級活動</strong>：</p><ul><li><p>每月舉行一次班級聚會，讓學生有機會表達自己、討論問題。</p></li><li><p>定期進行小組合作活動，增進學生間的合作精神。</p></li><li><p>課外活動時，要特別注意學生安全，事先通知家長。</p></li></ul></li><li><p><strong>家長聯繫</strong>：</p><ul><li><p>每週發送一次班級通訊，讓家長了解學生的學習與生活狀況。</p></li><li><p>定期舉行家長會議，與家長溝通學生的學習進度和行為表現。</p></li></ul></li><li><p><strong>心理健康</strong>：</p><ul><li><p>針對學生的情緒變化，設置每月一次的心理健康課程，幫助他們學會表達情感和解決問題。</p></li><li><p>若有學生出現焦慮或不安情緒，應及時與家長溝通，並尋求專業支持。</p></li></ul></li><li><p><strong>班級紀錄</strong>：</p><ul><li><p>記錄學生的日常表現，包括學業進度、行為表現等。</p></li><li><p>每週更新一次班級檔案，方便查看學生的進步與需要改進的地方。</p></li></ul></li></ul><p>5. <strong>其他補充事項</strong></p><ul><li><p><strong>教室佈置</strong>：</p><ul><li><p>教室內部的佈置應根據學期主題進行更換，例如：春天可以放上花朵與綠意，秋天則是豐收與收穫的象徵。</p></li><li><p>增設“表揚牆”，將學生的優秀作品或表現貼上去，給予正向鼓勵。</p></li></ul></li><li><p><strong>班級文化</strong>：</p><ul><li><p>設立一個“今天我學到了”區域，鼓勵學生每天分享他們學到的新知識。</p></li><li><p>每週選出“班級小幫手”，由學生輪流擔任，提升責任感。</p></li></ul></li></ul><p>這些內容可以幫助你更好地規劃班級經營，建立良好的學習氛圍和紀律。如果還有其他具體需求或問題，隨時告訴我！</p>",
